<script>
/* ================= CG 图库（之后填入图片链接即可） =================
 * 键为角色名（与世界书「人物：X」中的 X 一致）。
 *   头像：状态栏卡片左侧的小图
 *   阶段：按关系阶段切换的立绘，键为 戒备 / 陌生 / 熟悉 / 恋慕 / 不渝；没填的阶段回退到“头像”
 * 示例：
 *   '金克丝': { 头像: 'https://example.com/jinx.png', 阶段: { 恋慕: 'https://example.com/jinx_love.png' } },
 */
const CG_LIBRARY = {
};

const STAGES = ['戒备', '陌生', '熟悉', '恋慕', '不渝'];
const STAGE_COLOR = { 戒备: '--c-stage-hostile', 陌生: '--c-stage-stranger', 熟悉: '--c-stage-familiar', 恋慕: '--c-stage-love', 不渝: '--c-stage-devoted' };
const OPTION_TAGS = ['正常推进', '好感推进', '角色推进', '时间推进', '冒险推进', '超展开'];
const OUTFIT_LABELS = [['head', '发型'], ['upper', '上身'], ['lower', '下身'], ['acc', '配饰']];

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}
function stageOf(v) {
  if (v < 0) return '戒备';
  if (v < 350) return '陌生';
  if (v < 700) return '熟悉';
  if (v < 900) return '恋慕';
  return '不渝';
}
function stageBadge(stage) {
  const color = 'var(' + (STAGE_COLOR[stage] || '--c-stage-stranger') + ')';
  return '<span class="stage" style="color:' + color + '">' + esc(stage) + '</span>';
}
function affectionBar(v) {
  const n = Number(v);
  if (!isFinite(n)) return '';
  const stage = stageOf(n);
  const pct = Math.max(0, Math.min(100, (n + 100) / 11));
  const color = 'var(' + STAGE_COLOR[stage] + ')';
  return '<div class="bar"><i style="width:' + pct.toFixed(1) + '%;background:' + color + '"></i></div>' +
    '<div class="bar-num">好感度 ' + n + ' / 1000</div>';
}
function cgFor(name, stage) {
  const entry = CG_LIBRARY[name];
  if (!entry) return '';
  return (entry.阶段 && entry.阶段[stage]) || entry.头像 || '';
}

/* ---------- 读取数据 ---------- */
function inTavern() {
  return typeof getCurrentMessageId === 'function' && typeof getChatMessages === 'function';
}
function readMessageText() {
  if (!inTavern()) return window.__RT_DEMO_MESSAGE__ || '';
  try {
    const msg = getChatMessages(getCurrentMessageId())[0];
    return (msg && msg.message) || '';
  } catch (e) { return ''; }
}
function readStatData() {
  if (!inTavern()) return window.__RT_DEMO_STAT__ || {};
  try {
    const vars = getVariables({ type: 'message', message_id: getCurrentMessageId() });
    if (vars && vars.stat_data) return vars.stat_data;
  } catch (e) {}
  try {
    const vars = getVariables({ type: 'message', message_id: 'latest' });
    return (vars && vars.stat_data) || {};
  } catch (e) { return {}; }
}
function parseZtl(text) {
  const m = text.match(/<ztl>([\s\S]*?)<\/ztl>/i);
  if (!m) return null;
  const raw = m[1].trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(raw); } catch (e) {}
  try { return JSON.parse(raw.replace(/[“”]/g, '"')); } catch (e) {}
  return null;
}
function parseOptions(text) {
  const m = text.match(/<xuan>([\s\S]*?)<\/xuan>/i);
  if (!m) return [];
  return m[1].split('\n').map(l => l.trim()).filter(Boolean)
    .map(l => l.replace(/^\d+\s*[.、．)]\s*/, '').replace(/^\[|\]$/g, '').trim()).filter(Boolean).slice(0, 6);
}

/* ---------- 渲染 ---------- */
let currentTab = null;
let lastKey = '';

function renderHead(stat, ztl) {
  const w = stat.世界状态 || {};
  const items = [];
  const time = (ztl && ztl.time) || w.纪元时间;
  const where = (ztl && ztl.location) || [w.大地点, w.具体地点].filter(x => x && x !== '待定').join(' · ');
  if (time && time !== '待定') items.push(['时间', time]);
  if (where) items.push(['地点', where]);
  if (w.当前任务 && w.当前任务 !== '无') items.push(['任务', w.当前任务]);
  if (!items.length) items.push(['符文之地', '旅途尚未开始']);
  const dreamOn = ((w.梦境 || {}).是否处于梦境叙事中) === '是';
  document.getElementById('rt-head').innerHTML = items
    .map(([k, v]) => '<div class="item"><span class="label">' + esc(k) + '</span><span class="value">' + esc(v) + '</span></div>').join('') +
    '<button class="rt-dream' + (dreamOn ? ' on' : '') + '" title="切换梦境模式（写入最新楼层）"><i></i>梦境</button>';
}

function renderCharacters(stat, ztl) {
  const npcs = stat.近期NPC || {};
  const chars = (ztl && Array.isArray(ztl.characters)) ? ztl.characters : [];
  if (!chars.length) return '<div class="rt-empty">本轮没有在场角色的记录</div>';
  return chars.map(c => {
    const name = c.name || '身份不明者';
    const npc = npcs[name];
    const stage = npc ? (npc._关系阶段 || stageOf(Number(npc.好感度))) : '';
    const img = cgFor(name, stage);
    const art = img
      ? '<div class="ch-art has-img" data-cg="' + esc(img) + '" style="background-image:url(&quot;' + esc(img) + '&quot;)"></div>'
      : '<div class="ch-art">' + esc(name.slice(0, 1)) + '</div>';
    const o = c.outfit || {};
    const chips = OUTFIT_LABELS.filter(([k]) => o[k] && o[k] !== '无')
      .map(([k, label]) => '<span class="chip"><em>' + label + '</em>' + esc(o[k]) + '</span>').join('');
    return '<div class="ch">' + art + '<div class="ch-body">' +
      '<div class="ch-name"><b>' + esc(name) + '</b>' + (stage ? stageBadge(stage) : '') + '</div>' +
      (npc ? affectionBar(npc.好感度) : '') +
      (chips ? '<div class="outfit">' + chips + '</div>' : '') +
      (o.overview ? '<div class="overview">' + esc(o.overview) + '</div>' : '') +
      (c.thought ? '<div class="thought">' + esc(c.thought) + '</div>' : '') +
      '</div></div>';
  }).join('');
}

function renderBonds(stat) {
  const npcs = stat.近期NPC || {};
  const names = Object.keys(npcs);
  if (!names.length) return '<div class="rt-empty">还没有结识任何人</div>';
  names.sort((a, b) => Number(npcs[b].好感度) - Number(npcs[a].好感度));
  return names.map(name => {
    const npc = npcs[name] || {};
    const stage = npc._关系阶段 || stageOf(Number(npc.好感度));
    const n = Number(npc.好感度);
    const pct = Math.max(0, Math.min(100, (n + 100) / 11));
    const color = 'var(' + STAGE_COLOR[stage] + ')';
    return '<div class="bond"><b>' + esc(name) + '</b>' +
      '<div class="bar"><i style="width:' + pct.toFixed(1) + '%;background:' + color + '"></i></div>' +
      '<span>' + stageBadge(stage) + ' <span class="bar-num">' + (isFinite(n) ? n : '?') + '</span></span></div>';
  }).join('');
}

function renderHero(stat) {
  const h = stat.主角 || {};
  const s = h.状态 || {};
  let html = '<div class="kv">' +
    '<span class="k">能级</span><span class="v">' + esc(h.基础能级 || '待定') + '</span>' +
    '<span class="k">伤势</span><span class="v">' + esc(s.伤势等级 || '无伤') + '</span>' +
    '<span class="k">魔力</span><span class="v">' + esc(s.魔法能量透支状态 || '正常') + '</span></div>';
  const money = Object.entries(h.财富资产 || {});
  html += '<div class="sec"><div class="sec-title">财富</div>' +
    (money.length ? money.map(([k, v]) => '<div class="item-row"><span>' + esc(k) + '</span><b>' + esc(v) + '</b></div>').join('') : '<div class="rt-empty">身无分文</div>') + '</div>';
  const items = Object.entries(h.物品栏 || {});
  html += '<div class="sec"><div class="sec-title">物品栏</div>' +
    (items.length ? items.map(([k, v]) => '<div class="item-row"><span>' + esc(k) + (v && v.描述 ? '<small>' + esc(v.描述) + '</small>' : '') + '</span><b>×' + esc(v && v.数量) + '</b></div>').join('') : '<div class="rt-empty">空空如也</div>') + '</div>';
  return html;
}

function renderRep(stat) {
  const rep = Object.entries((stat.世界状态 || {}).各方势力声望 || {});
  if (!rep.length) return '<div class="rt-empty">尚未与任何势力产生交集</div>';
  return rep.map(([k, v]) => '<span class="rep">' + esc(k) + ' · <b>' + esc(v) + '</b></span>').join('');
}

function renderOptions(options) {
  const box = document.getElementById('rt-opts');
  if (!options.length) { box.style.display = 'none'; return; }
  box.style.display = '';
  document.getElementById('rt-opt-list').innerHTML = options.map((o, i) =>
    '<button class="opt" data-text="' + esc(o) + '"><span class="tag">' + (OPTION_TAGS[i] || ('选项' + (i + 1))) + '</span><span>' + esc(o) + '</span></button>').join('');
