function render() {
  try { renderUnsafe(); } catch (e) {
    document.getElementById('rt-pages').innerHTML = '<div class="rt-err">状态面板出错：' + esc(e && e.message ? e.message : e) + '</div>';
  }
}

async function toggleDream() {
  const opt = { type: 'message', message_id: 'latest' };
  try {
    if (typeof Mvu !== 'undefined' && Mvu && Mvu.getMvuData) {
      const data = Mvu.getMvuData(opt) || {};
      const cur = _.get(data, 'stat_data.世界状态.梦境.是否处于梦境叙事中', '否');
      _.set(data, 'stat_data.世界状态.梦境.是否处于梦境叙事中', cur === '是' ? '否' : '是');
      await Mvu.replaceMvuData(data, opt);
    } else if (typeof updateVariablesWith === 'function') {
      updateVariablesWith(vars => {
        const cur = _.get(vars, 'stat_data.世界状态.梦境.是否处于梦境叙事中', '否');
        _.set(vars, 'stat_data.世界状态.梦境.是否处于梦境叙事中', cur === '是' ? '否' : '是');
        return vars;
      }, opt);
