  }
  lastKey = '';
  setTimeout(render, 300);
}

function renderUnsafe() {
  const text = readMessageText();
  const stat = readStatData();
  const key = text.length + '|' + JSON.stringify(stat);
  if (key === lastKey) return;
  lastKey = key;

  const ztl = parseZtl(text);
  renderHead(stat, ztl);

  const npcCount = Object.keys(stat.近期NPC || {}).length;
  const pages = [];
  if (ztl) pages.push(['scene', '在场', renderCharacters(stat, ztl), (ztl.characters || []).length]);
  pages.push(['bond', '羁绊', renderBonds(stat), npcCount]);
  pages.push(['hero', '主角', renderHero(stat), null]);
  pages.push(['rep', '声望', renderRep(stat), null]);
  if (!currentTab || !pages.some(p => p[0] === currentTab)) currentTab = pages[0][0];

  document.getElementById('rt-tabs').innerHTML = pages.map(([id, label, , n]) =>
    '<button class="rt-tab' + (id === currentTab ? ' on' : '') + '" data-tab="' + id + '">' + label +
    (n ? '<span class="n">' + n + '</span>' : '') + '</button>').join('');
  document.getElementById('rt-pages').innerHTML = pages.map(([id, , html]) =>
    '<div class="rt-page' + (id === currentTab ? ' on' : '') + '" data-page="' + id + '">' + html + '</div>').join('');

  renderOptions(parseOptions(text));
