/* ---------- 交互 ---------- */
document.addEventListener('click', ev => {
  if (ev.target.closest('.rt-dream')) { toggleDream(); return; }
  const tab = ev.target.closest('.rt-tab');
  if (tab) {
    currentTab = tab.dataset.tab;
    document.querySelectorAll('.rt-tab').forEach(t => t.classList.toggle('on', t === tab));
    document.querySelectorAll('.rt-page').forEach(p => p.classList.toggle('on', p.dataset.page === currentTab));
