  const art = ev.target.closest('.ch-art.has-img');
  if (art) {
    document.getElementById('cg-img').src = art.dataset.cg;
    document.getElementById('cg-view').classList.add('on');
    return;
  }
  if (ev.target.closest('#cg-view')) document.getElementById('cg-view').classList.remove('on');
});

(async function start() {
  render();
  if (inTavern()) {
    try { if (typeof waitGlobalInitialized === 'function') await waitGlobalInitialized('Mvu'); } catch (e) {}
    render();
    setInterval(render, 2000);
